def fitness_function(tree, X, y):
    """Robust error with mild intrinsic size regularization. Lower is better.

    Uses a log-compressed MSE to reduce domination by numerical blowups and
    adds a very small size term so selection prefers simpler equally-good
    programs, while the main loop still tracks genuine predictive quality.
    """
    y_pred = safe_evaluate(tree, X)
    mse = float(np.mean((y - y_pred) ** 2))
    return float(np.log1p(mse) + 1e-4 * tree.size())


def _tree_size_bias_index(population, scores, sample_k=7):
    """Size-biased tournament: rank by score, break ties toward smaller trees."""
    candidates = random.sample(range(len(population)), min(sample_k, len(population)))
    return min(candidates, key=lambda i: (scores[i], population[i].size()))


def _subtree_at(root, point):
    nodes = root.get_all_nodes()
    return nodes[point]


def selection(population, fitnesses, n_select):
    """Novel mixed selection: quality-diversity tournaments.

    Half the time select by scalar fitness tournament, half the time by
    random-case residual tournament. This encourages specialists that solve
    hard training cases while keeping global progress pressure.
    """
    selected = []
    case_errors = None
    if isinstance(fitnesses, tuple):
        scalar_fitnesses, case_errors = fitnesses
    else:
        scalar_fitnesses = fitnesses

    for _ in range(n_select):
        if case_errors is not None and random.random() < 0.5:
            case = random.randint(0, case_errors.shape[1] - 1)
            candidates = random.sample(range(len(population)), min(7, len(population)))
            best = min(candidates, key=lambda i: (case_errors[i, case], scalar_fitnesses[i], population[i].size()))
            selected.append(population[best].copy())
        else:
            best = _tree_size_bias_index(population, scalar_fitnesses, sample_k=7)
            selected.append(population[best].copy())
    return selected


def crossover(parent1, parent2, n_features, max_depth=17):
    """Homologous-size subtree crossover with depth-safe fallback."""
    offspring = parent1.copy()
    donor = parent2.copy()
    off_nodes = offspring.get_all_nodes()
    don_nodes = donor.get_all_nodes()
    if len(off_nodes) <= 1 or len(don_nodes) <= 1:
        return offspring

    off_point = random.randint(1, len(off_nodes) - 1)
    target_node, parent, child_idx = off_nodes[off_point]
    target_size = target_node.size()

    donor_candidates = []
    for j, (dnode, _, _) in enumerate(don_nodes):
        if j == 0 or abs(dnode.size() - target_size) <= max(2, target_size // 2):
            donor_candidates.append(j)
    don_point = random.choice(donor_candidates)
    donor_subtree = don_nodes[don_point][0].copy()

    if parent is not None:
        parent.children[child_idx] = donor_subtree
    else:
        offspring = donor_subtree

    if offspring.depth() > max_depth:
        return parent1.copy()
    return offspring


def mutation(parent, n_features, max_depth=17):
    """Context-aware mutation: mostly subtree mutation, sometimes point mutation."""
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    if len(nodes) == 0:
        return generate_tree('grow', 3, n_features)

    mut_point = random.randint(0, len(nodes) - 1)
    node, par, child_idx = nodes[mut_point]

    if (not node.is_terminal) and random.random() < 0.35:
        # Point mutation: preserve arity, alter operator.
        _, arity = OPERATORS[node.value]
        compatible = [name for name, (_, a) in OPERATORS.items() if a == arity and name != node.value]
        if compatible:
            node.value = random.choice(compatible)
    elif node.is_terminal and random.random() < 0.5:
        # Terminal refresh for local numeric exploration.
        new_subtree = random_terminal(n_features)
        if par is not None:
            par.children[child_idx] = new_subtree
        else:
            offspring = new_subtree
    else:
        # Size-aware subtree mutation: regrow near current subtree depth.
        local_depth = min(3, max(1, node.depth() + 1))
        new_subtree = generate_tree('grow', local_depth, n_features)
        if par is not None:
            par.children[child_idx] = new_subtree
        else:
            offspring = new_subtree

    if offspring.depth() > max_depth:
        return parent.copy()
    return offspring


def evolve_one_generation(population, fitnesses, X_train, y_train,
                          n_features, pop_size,
                          crossover_rate=0.9, mutation_rate=0.05,
                          max_depth=17):
    """Residual-diversity GP with adaptive parsimony and restricted replacement."""
    new_population = []

    raw_fit = np.array(fitnesses, dtype=float)
    sizes = np.array([tree.size() for tree in population], dtype=float)

    # Adaptive selection pressure: penalize size only when it correlates with poor fit.
    size_var = float(np.var(sizes))
    if size_var > 1e-15:
        parsimony = float(np.cov(sizes, raw_fit)[1, 0]) / size_var
        parsimony = min(max(parsimony, 0.0), 0.003)
    else:
        parsimony = 0.0
    scalar_scores = list(raw_fit + parsimony * sizes)

    # Case-wise residuals for specialist-preserving parent selection.
    case_errors = np.empty((len(population), X_train.shape[0]))
    for i, tree in enumerate(population):
        case_errors[i] = np.abs(y_train - safe_evaluate(tree, X_train))

    # Keep two elites: best fit and best compact model among near-elites.
    elite_idx = int(np.argmin(raw_fit))
    new_population.append(population[elite_idx].copy())
    near = [i for i, f in enumerate(raw_fit) if f <= raw_fit[elite_idx] * 1.05 + 1e-12]
    if near:
        compact_idx = min(near, key=lambda i: population[i].size())
        if compact_idx != elite_idx and len(new_population) < pop_size:
            new_population.append(population[compact_idx].copy())

    parent_scores = (scalar_scores, case_errors)
    while len(new_population) < pop_size:
        r = random.random()
        if r < crossover_rate:
            parents = selection(population, parent_scores, 2)
            child = crossover(parents[0], parents[1], n_features, max_depth)
        elif r < crossover_rate + mutation_rate + 0.1:
            parents = selection(population, parent_scores, 1)
            child = mutation(parents[0], n_features, max_depth)
        else:
            parents = selection(population, parent_scores, 1)
            child = parents[0]
        new_population.append(child)

    return new_population[:pop_size]

def fitness_function(tree, X, y):
    """Training MSE for honest elite tracking; search shaping happens elsewhere."""
    y_pred = safe_evaluate(tree, X)
    return float(np.mean((y - y_pred) ** 2))


def _per_case_errors(population, X, y):
    errors = np.empty((len(population), X.shape[0]))
    for i, tree in enumerate(population):
        errors[i] = np.abs(y - safe_evaluate(tree, X))
    return errors


def _mixed_select_index(population, scalar_scores, case_errors=None):
    """Difficulty-aware hybrid selector.

    Novelty: sample hard training cases with probability proportional to how much
    error remains on that case in the current population, then run a restricted
    tournament on that case; otherwise run ordinary fitness tournament with size
    tie-breaking. This focuses search on unsolved regions without fully giving up
    aggregate fitness pressure.
    """
    pop_size = len(population)
    candidates = random.sample(range(pop_size), min(7, pop_size))

    if case_errors is not None and random.random() < 0.6:
        case_difficulty = np.mean(case_errors, axis=0)
        total = float(np.sum(case_difficulty))
        if total > 1e-12:
            probs = case_difficulty / total
            case = int(np.random.choice(case_errors.shape[1], p=probs))
        else:
            case = random.randint(0, case_errors.shape[1] - 1)
        return min(candidates, key=lambda i: (case_errors[i, case], scalar_scores[i], population[i].size()))

    return min(candidates, key=lambda i: (scalar_scores[i], population[i].size()))


def selection(population, fitnesses, n_select):
    """Hybrid parent selection using scalar and difficulty-weighted case fitness."""
    selected = []
    if isinstance(fitnesses, tuple):
        scalar_scores, case_errors = fitnesses
    else:
        scalar_scores, case_errors = fitnesses, None
    for _ in range(n_select):
        idx = _mixed_select_index(population, scalar_scores, case_errors)
        selected.append(population[idx].copy())
    return selected


def crossover(parent1, parent2, n_features, max_depth=17):
    """Context-preserving crossover with size matching and retry."""
    off_nodes_src = parent1.get_all_nodes()
    don_nodes_src = parent2.get_all_nodes()
    if len(off_nodes_src) <= 1 or len(don_nodes_src) <= 1:
        return parent1.copy()

    best_child = parent1.copy()
    best_score = (best_child.depth(), best_child.size())
    for _ in range(3):
        offspring = parent1.copy()
        donor = parent2.copy()
        off_nodes = offspring.get_all_nodes()
        don_nodes = donor.get_all_nodes()

        off_point = random.randint(1, len(off_nodes) - 1)
        target_node, parent, child_idx = off_nodes[off_point]
        target_size = target_node.size()
        donor_candidates = [j for j, (dnode, _, _) in enumerate(don_nodes)
                            if abs(dnode.size() - target_size) <= max(2, target_size // 2)]
        if not donor_candidates:
            donor_candidates = list(range(len(don_nodes)))
        don_point = random.choice(donor_candidates)
        donor_subtree = don_nodes[don_point][0].copy()

        if parent is not None:
            parent.children[child_idx] = donor_subtree
        else:
            offspring = donor_subtree

        if offspring.depth() <= max_depth:
            cand_score = (offspring.depth(), offspring.size())
            if cand_score < best_score:
                best_child, best_score = offspring, cand_score
    return best_child


def mutation(parent, n_features, max_depth=17):
    """Multi-mode mutation emphasizing constant/terminal refinement and simplification."""
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    if not nodes:
        return generate_tree('grow', 3, n_features)

    mut_point = random.randint(0, len(nodes) - 1)
    node, par, child_idx = nodes[mut_point]
    r = random.random()

    if node.is_terminal and r < 0.45:
        if isinstance(node.value, str) and not node.value.startswith('x'):
            try:
                val = float(node.value)
                node.value = str(round(val + random.uniform(-1.0, 1.0), 2))
            except Exception:
                node.value = random_terminal(n_features).value
        else:
            new_subtree = random_terminal(n_features)
            if par is not None:
                par.children[child_idx] = new_subtree
            else:
                offspring = new_subtree
    elif (not node.is_terminal) and r < 0.7:
        _, arity = OPERATORS[node.value]
        compatible = [name for name, (_, a) in OPERATORS.items() if a == arity and name != node.value]
        if compatible:
            node.value = random.choice(compatible)
    else:
        new_depth = min(3, max(1, node.depth() + 1))
        new_subtree = generate_tree('grow', new_depth, n_features)
        if par is not None:
            par.children[child_idx] = new_subtree
        else:
            offspring = new_subtree

    if offspring.depth() > max_depth:
        return parent.copy()
    return offspring


def evolve_one_generation(population, fitnesses, X_train, y_train,
                          n_features, pop_size,
                          crossover_rate=0.9, mutation_rate=0.05,
                          max_depth=17):
    """Difficulty-aware residual GP with near-elite compaction.

    Contributions:
    1) difficulty-weighted case tournament selection,
    2) adaptive parsimony applied only to parent choice,
    3) near-elite compact archive to improve generalization and reduce bloat.
    """
    new_population = []
    raw_fit = np.array(fitnesses, dtype=float)
    sizes = np.array([tree.size() for tree in population], dtype=float)

    size_var = float(np.var(sizes))
    if size_var > 1e-15:
        parsimony = float(np.cov(sizes, raw_fit)[1, 0]) / size_var
        parsimony = min(max(parsimony, 0.0), 0.002)
    else:
        parsimony = 0.0
    scalar_scores = list(raw_fit + parsimony * sizes)
    case_errors = _per_case_errors(population, X_train, y_train)

    elite_idx = int(np.argmin(raw_fit))
    new_population.append(population[elite_idx].copy())

    near = [i for i, f in enumerate(raw_fit) if f <= raw_fit[elite_idx] * 1.1 + 1e-12]
    near_sorted = sorted(near, key=lambda i: (population[i].size(), raw_fit[i]))
    for i in near_sorted[:2]:
        if i != elite_idx and len(new_population) < pop_size:
            new_population.append(population[i].copy())

    parent_scores = (scalar_scores, case_errors)
    while len(new_population) < pop_size:
        r = random.random()
        if r < crossover_rate:
            parents = selection(population, parent_scores, 2)
            child = crossover(parents[0], parents[1], n_features, max_depth)
        elif r < crossover_rate + mutation_rate + 0.15:
            parents = selection(population, parent_scores, 1)
            child = mutation(parents[0], n_features, max_depth)
        else:
            parents = selection(population, parent_scores, 1)
            child = parents[0]
        new_population.append(child)

    return new_population[:pop_size]
